{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The title is 'Community health workers for noncommunicable diseases prevention and control in developing countries: Evidence and implications' and does not contain the term 'systematic review' or any equivalent label identifying the report as a systematic review. No retrieved evidence shows the title identifying the report as such."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Community health workers for noncommunicable diseases prevention and control in developing countries: Evidence and implications",
      "reason": "The title conveys the main objective/review question by specifying the intervention (community health workers), the population/health focus (noncommunicable diseases), and the setting (developing countries)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "A systematic review of trials that utilised community health workers for primary prevention/ early detection strategy in the management of NCDs ... in LMICs was conducted.",
      "reason": "The review is a new (non-updated, non-living) systematic review; no special analysis method, study design label, update, or living-review status applies as supplementary title information, so this conditional element does not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "However, studies assessing their effectiveness in delivering primary prevention interventions for non-communicable disease prevention and control in LMIC settings are limited,[10] though this has been proven for developed countries.[11] Further, whatever sparse results are available are mostly through observational studies and evidence from controlled trials needs to be synthesised.",
      "reason": "The Background describes the current state of knowledge (CHWs effective in developed countries, cost-effective, used in NCD programs) and the key uncertainty: limited and mostly observational evidence on their effectiveness for NCD prevention in LMICs."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Considering this deficiency in availability of effectiveness parameters, a systematic review on effectiveness of CHW delivered primary prevention interventions for NCDs in developing countries was conducted by the authors.",
      "reason": "The need for the review is explicitly explained: the deficiency in effectiveness evidence justifies conducting this systematic review, with a stated hypothesis."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Only four systematic reviews assessing this effectiveness in LMIC/ developing countries could be identified after review of published literature.[11-14] Considering this deficiency in availability of effectiveness parameters, a systematic review on effectiveness of CHW delivered primary prevention interventions for NCDs in developing countries was conducted",
      "reason": "The manuscript identifies and cites four previous systematic reviews, but it does not explicitly explain how the current review differs from, updates, or extends those prior reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "A community health worker (CHW) delivers NCD preventive services using informational as well as behavioural approaches. Community education and interpersonal communication on lifestyle modifications is imparted with focus on primordial prevention of NCDs and screening is conducted as part of early diagnosis and management.",
      "reason": "The mechanism of action of the CHW intervention (informational and behavioural approaches, education, interpersonal communication, screening) is briefly described in the Background."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or diagram showing hypothesised relationships between CHW intervention components and outcomes is reported anywhere in the retrieved evidence."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Considering this deficiency in availability of effectiveness parameters, a systematic review on effectiveness of CHW delivered primary prevention interventions for NCDs in developing countries was conducted by the authors. This was conducted following the hypothesis that for NCD control programs employing a community health worker is more likely to be successful than routine care.",
      "reason": "The review's aim and hypothesis are conveyed in the Background, but there is no explicit, formally stated objective or research question using a question-formulation framework (e.g., PICO-formatted objective statement); the objective is only implicit in narrative form."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although this is a review of intervention effects (CHW interventions vs usual care), no planned comparisons are explicitly stated using PICO or a variant in the retrieved evidence; comparisons appear only implicitly via included trial characteristics (e.g., Table 1) and methods text."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "A research was considered eligible for inclusion if it followed a randomised controlled study design in community settings of low middle income countries with community health worker as intervention delivery person for general or high risk population for primary prevention of NCDs as compared to routine care or enhanced routine care as comparator.",
      "reason": "The seven-point eligibility criteria specify study design (RCT/cRCT), setting (community settings in LMICs), population (general or high-risk), intervention (CHW-delivered), comparator, and purpose (primary prevention of NCDs)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Only randomised controlled trials (community based randomised controlled trial, cluster randomised trials) published in the last 15 years (2000-2015) were included in the review... without restriction to language",
      "reason": "Publication year restriction (2000-2015) and no language restriction are explicitly stated; unpublished reports were also considered."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion due to outcomes not measured versus outcomes not reported; no such distinction is reported in the retrieved text."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_16",
      "quote": "Meta-analyses were carried out separately for each outcome and type of study design (RCT/ cRCT)... In case of considerable heterogeneity (I 2 > 75%) we only carried out a narrative synthesis of the results and grouped our findings by the type of outcome measured.",
      "reason": "Synthesis grouping by outcome type and study design is described, and subgroups by age/sex are mentioned, but explicit linkage of synthesis groups to review objective comparisons is only partially elaborated."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "The time period was limited to base evidence on recently conducted studies in light of recent shift in delivery of primary health care services towards NCDs in most of the developing countries.",
      "reason": "A rationale for the 15-year publication restriction is explicitly provided, tied to the shift of primary health care toward NCDs after 2000."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_6",
  "elements": [
    {
      "element_id": "prisma_2020_6_e1",
      "status": "MISSING",
      "chunk_id": "text_13",
      "quote": "Searches of published literature ... were done in the following biomedical, and general reference electronic databases, without restriction to language: PubMed (20002015); Excerpta Medica Database (EMBASE) (2000-2015); OVID (2000-2015)",
      "reason": "Only coverage date ranges (2000-2015) are given; no date on which each source was last searched or consulted is reported."
