    {
      "element_id": "prisma_2020_6_e5",
      "status": "MISSING",
      "chunk_id": "text_13",
      "quote": "Authors or trial investigators for further information were contacted for queries pertaining to methodology, study outcome, availability of trial reports",
      "reason": "Individual authors/investigators were contacted, but no organisations or manufacturers contacted to identify studies are named."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Authors or trial investigators for further information were contacted for queries pertaining to methodology, study outcome, availability of trial reports (if results not yet published as journal article).",
      "reason": "The types of individuals contacted (authors or trial investigators) and purpose are described."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "In addition, reference lists and bibliographies of previous systematic and non- systematic reviews were screened",
      "reason": "The types of reference lists examined (previous systematic and non-systematic reviews) are specified."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "citation tracking were undertaken to identify relevant studies",
      "reason": "Citation tracking (forward citation searching) is mentioned, but no citation index/platform, seed reports, or search date are reported."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No journals or conference proceedings were consulted as search sources according to the evidence; only handsearching of reference lists is reported."
    }
  ],
  "confidence": 88
}

