{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "The primary outcome of review was percentage change in population with different behavioural risk factors. Additionally, mean overall changes in levels of several physical or biochemical parameters were studied as secondary outcomes.",
      "reason": "Primary and secondary outcome domains are stated (behavioural risk factors; physical/biochemical parameters), but the domains are described broadly without explicit definitions of each outcome."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No time frame of measurement (e.g. follow-up duration or time points) is specified for any outcome domain in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The outcome abstraction from the trials was not limited to the primary outcome on which the trial was based. Efforts were made to pool results for all other reported outcomes to highlight the fact that primary prevention interventions for NCDs influence several risk factors simultaneously.",
      "reason": "The authors explicitly state that data abstraction sought all compatible reported outcomes, not only trial primary outcomes."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Studies were pooled only if the outcomes had been measured in the same way by all studies. Where the change per group was not available [26, 30], we used end-values where randomisation was successful.",
      "reason": "Methods for selecting which results to collect/pool are described: homogeneity of measurement required and use of end-values when change scores unavailable."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion or definitions from the registered PROSPERO protocol are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to the processes for selecting results within outcome domains are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "The primary outcome of review was percentage change in population with different behavioural risk factors.",
      "reason": "A primary outcome is identified, implicitly prioritising behavioural risk factors, but no explicit rationale for this prioritisation for interpreting conclusions is provided."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The tool was adapted from The Cochrane Public Health Group: Data Extraction and Assessment Template to collect information on all aspects deemed necessary as per MECIR standards[23] from studies included in the review. Primarily it captured the trial's methodological approach as well as specifics regarding how effects of the intervention were assessed. Additionally, it also collected data on methodology used for CHW selection, training, terms used to describe the CHWandtheir supervision.",
      "reason": "The variables sought are listed: methodological approach, intervention effect assessment, CHW selection, training, terminology, and supervision; Table 1 and S Tables further document participant/intervention characteristics."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "None of the included trials had unclear or missing data related to study methodology, participants' lost to follow-up, primary outcome data, or statistical parameters, however minor queries related to data or outcome were there, for which we contacted the study's primary author via email. We recorded all missing secondary outcome data in the data extraction form and in the risk of bias table.",
      "reason": "The authors describe assumptions and handling of missing or unclear information: author contact via email and recording of missing secondary outcome data."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The tool was adapted from The Cochrane Public Health Group: Data Extraction and Assessment Template to collect information on all aspects deemed necessary as per MECIR standards[23]",
      "reason": "The data extraction tool is explicitly cited (adapted from The Cochrane Public Health Group Data Extraction and Assessment Template, with reference to MECIR standards)."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Quality Rating of Individual trials was done using Hamilton Effective Public Health Practice Project Checklist for quantitative studies.[24] ... Additionally, Cochrane risk of bias tool was used to assess risk of bias.[25]",
      "reason": "Both risk-of-bias tools (EPHPP checklist and Cochrane risk of bias tool) are named."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "For each item, a judgement of 'High risk', 'Unclear risk', or 'Low risk' was made.",
      "reason": "The response scale for Cochrane tool items is given, and Fig 2 (text_15, figure_12) visually shows the assessed domains (random sequence generation, allocation concealment, blinding, incomplete outcome data, selective reporting, other bias, baseline imbalance), but the domains of the EPHPP checklist are not described in text."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "The quality assessment represented as global score is included in the 'Characteristics of included studies' table. (Table 1)",
      "reason": "An overall global quality score is reported (Strong/Moderate/Weak in Table 1), but the rules used to derive the overall judgement are not described."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No adaptations to the existing risk-of-bias tools are described; adaptations mentioned relate to a data extraction tool, not the risk-of-bias tools."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Only established tools (EPHPP, Cochrane RoB) were used; no newly developed risk-of-bias tool is reported."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
